INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6201, 'Judges 6:16', 'Judges', 6, 16, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”خو زۀ به ستا مل يم او تۀ به ميديانيان داسې ووهې لکه چې هغوئ صِرف يو کس وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6202, 'Judges 6:17', 'Judges', 6, 17, '&nbsp;جدعون جواب ورکړو، ”کۀ تۀ زما نه خوشحاله يې نو ما ته څۀ نښې وښايه چې تۀ په رښتيا مالِک خُدائ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6203, 'Judges 6:18', 'Judges', 6, 18, '&nbsp;تۀ تر هغې پورې دلته ايسار شه چې زۀ تا له خپله نذرانه راوړم.“ هغۀ ورته وفرمائيل، ”زۀ به ستا تر واپس راتلو پورې ايسار يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6204, 'Judges 6:19', 'Judges', 6, 19, '&nbsp;نو جدعون خپل کور ته دننه لاړو او يو د چېلۍ بچے يې پوخ کړو او د لسو کلو اوړو نه يې پتيره روټۍ تياره کړه. هغۀ غوښه په يوه ټوکرۍ کښې کېښوده او ښوروا يې په يو لوښى کښې واچوله او دا يې د مالِک خُدائ فرښتې له ورکړل چې د څېړۍ د ونې لاندې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6205, 'Judges 6:20', 'Judges', 6, 20, '&nbsp;فرښتې هغۀ له حُکم ورکړو، ”غوښه او روټۍ په دې ګټ باندې کېږده او ښوروا ورباندې واچوه.“ نو جدعون هم داسې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6206, 'Judges 6:21', 'Judges', 6, 21, '&nbsp;بيا د مالِک خُدائ فرښتې چې کومه امسا نيولې وه د هغې سر يې د غوښې او روټۍ سره ولګولو. د ګټ نه اور راووتلو او غوښه او روټۍ يې وسوزوله. فرښته بيا پناه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6207, 'Judges 6:22', 'Judges', 6, 22, '&nbsp;جدعون ته دا پته ولګېده چې هغۀ د مالِک خُدائ فرښته ليدلې ده او په يره کښې هغۀ وفرمائيل، ”مالِکه خُدايه پاکه، ما ستا فرښته مخامخ وليدله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6208, 'Judges 6:23', 'Judges', 6, 23, '&nbsp;خو مالِک خُدائ هغۀ ته وفرمائيل، ”تا ته دې خېر وى. مۀ يرېږه. تۀ به نۀ مرې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6209, 'Judges 6:24', 'Judges', 6, 24, '&nbsp;جدعون هلته مالِک خُدائ ته يوه قربان‌ګاه جوړه کړه او ”مالِک خُدائ خېر دے“ نوم يې پرې کېښودو. دا تر اوسه پورې په عفره کښې ولاړه ده چې دا د ابيعزر د قبيلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6210, 'Judges 6:25', 'Judges', 6, 25, '&nbsp;په هغه شپه مالِک خُدائ جدعون ته وفرمائيل، ”د خپل پلار غوَيے او يو بل غوَيے چې د اوو کالونو وى بوځه، د خپل پلار قربان‌ګاه راوغورزوه چې د بعل دپاره ده او د هغې په خوا کښې د اشيرې ستنه ماته کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6211, 'Judges 6:26', 'Judges', 6, 26, '&nbsp;په دې لوړ ځائ باندې مالِک خُدائ خپل خُدائ پاک ته يوه صحيح قربان‌ګاه جوړه کړه. بيا هغه دوېم غوَيے بوځه او د يوې قربانۍ په توګه يې پوره وسوزوه، د دې په سوزولو کښې د اشيرې د ستنې لرګى استعمال کړه چې تا ټوټې ټوټې کړې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6212, 'Judges 6:27', 'Judges', 6, 27, '&nbsp;نو جدعون خپل لس نوکران بوتلل او هم هغه شان يې وکړل چې څنګه مالِک خُدائ ورته فرمائيلى وُو. هغه د خپل خاندان او د ښار د خلقو نه سخت يرېدو چې د ورځې يې داسې کړے وے، نو هغۀ د شپې داسې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6213, 'Judges 6:28', 'Judges', 6, 28, '&nbsp;کله چې په ورپسې سحر د ښار خلق وختى پاڅېدل نو هغوئ ته پته ولګېده چې د بعل قربان‌ګاه او د اشيرې نښې ماتې شوې دى او دوېم غوَيے په هغه قربان‌ګاه باندې سوزولے شوے دے چې هلته جوړه شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6214, 'Judges 6:29', 'Judges', 6, 29, '&nbsp;هغوئ د يو بل نه تپوس وکړو، ”دا چا کړى دى؟“ هغوئ ښۀ معلومات وکړو او پته ورته ولګېده چې د يوآس زوئ جدعون دا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6215, 'Judges 6:30', 'Judges', 6, 30, '&nbsp;نو بيا هغوئ يوآس ته ووئيل، ”خپل زوئ دلته بهر راوباسه چې مړ يې کړُو. ځکه چې هغۀ د بعل قربان‌ګاه تباه کړې ده او د اشيرې ستنه يې ټوټې کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6216, 'Judges 6:31', 'Judges', 6, 31, '&nbsp;خو يوآس هغه ټولو ته ووئيل چا يې چې مخالفت کولو، ”تاسو د بعل صفائى کوئ څۀ؟ تاسو د هغۀ دپاره بحث کوئ؟ هر څوک چې د هغۀ صفائى کوى نو هغه به د سحر نه مخکښې ووژلے شى. کۀ بعل خُدائ وى، نو هغه دې خپل ځان بچ کړى. دا د هغۀ قربان‌ګاه وه چې تباه کړے شوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6217, 'Judges 6:32', 'Judges', 6, 32, '&nbsp;نو د هغه وخت نه جدعون په يربعل باندې مشهور شو، کله چې يوآس وئيلى وُو، ”پرېږده چې بعل خپل ځان بچ کړى، دا د هغۀ قربان‌ګاه ده چې تباه کړے شوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6218, 'Judges 6:33', 'Judges', 6, 33, '&nbsp;نو ټول ميديانيان، عماليقيان او د صحرا قبيلې راغونډې شوې، د اُردن سيند نه پورې وتل او د يزرعيل په مېدان کښې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6219, 'Judges 6:34', 'Judges', 6, 34, '&nbsp;د مالِک خُدائ روح په جدعون نازل شو، نو هغۀ بيګل وغږولو او د ابيعزر د قبيلې سړى يې راوغوښتل چې هغۀ پسې روان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6220, 'Judges 6:35', 'Judges', 6, 35, '&nbsp;هغۀ د منسى ټولې علاقې دواړو برخو ته پېغام وړُونکى ولېږل چې هغوئ راوغواړى او چې دۀ پسې روان شى. هغۀ د آشر، زبولون او نفتالى قبيلو ته پېغام وړُونکى ولېږل او هغوئ هم د دۀ سره شاملېدو دپاره راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6221, 'Judges 6:36', 'Judges', 6, 36, '&nbsp;بيا جدعون خُدائ پاک ته وفرمائيل، ”تۀ وائې چې دا فېصله دې کړې ده چې تۀ به ما د بنى اِسرائيلو د خلاصولو دپاره استعمالوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6222, 'Judges 6:37', 'Judges', 6, 37, '&nbsp;ټيک ده، زۀ به په درمند باندې دا وړۍ وغوړوم. خو کۀ په سحر کښې پرخه صِرف په وړۍ باندې وى او په زمکه باندې نۀ وى، نو ما ته به پته ولګى چې د بنى اِسرائيلو بچ کولو دپاره به تۀ ما استعمالوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6223, 'Judges 6:38', 'Judges', 6, 38, '&nbsp;نو هم دغه شان وشول. کله چې جدعون ورپسې سحر وختى پاڅېدو، هغۀ وړۍ نچوړ کړه او دومره ډېره پرخه يې ترې نه وويستله چې د اوبو نه يې يو لوښے ډک شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6224, 'Judges 6:39', 'Judges', 6, 39, '&nbsp;جدعون خُدائ پاک ته وفرمائيل، ”ما ته مۀ غصه کېږه، ما له اجازت راکړه چې صِرف يوه خبره وکړم. ما لږ پرېږده چې په وړۍ باندې يو بل آزمېښت وکړم. دا ځل پرېږده چې وړۍ اوچه وى او زمکه لمده وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6225, 'Judges 6:40', 'Judges', 6, 40, '&nbsp;په هغه شپه خُدائ پاک هغه هر څۀ وکړل. په ورپسې سحر وړۍ اوچه وه، خو زمکه په پرخه باندې لونده وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6226, 'Judges 7:1', 'Judges', 7, 1, '&nbsp;يوه ورځ جدعون او د هغۀ ټول سړى وختى پاڅېدل او د حرود چينې په خوا کښې يې خېمې ولګولې. د ميديانيانو خېمې د هغوئ شمالى طرف ته په مېدان کښې د موره غر ته نزدې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6227, 'Judges 7:2', 'Judges', 7, 2, '&nbsp;مالِک خُدائ جدعون ته وفرمائيل، ”تا سره چې کوم سړى دى دا زما دپاره ډېر زيات دى چې هغوئ له په ميديانيانو باندې فتح ورکړم. کېدے شى چې هغوئ دا سوچ وکړى چې هغوئ د خپل طاقت سره دا ګټه موندلې ده، نو مغروره به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6228, 'Judges 7:3', 'Judges', 7, 3, '&nbsp;خلقو ته اِعلان وکړه، هر څوک چې يرېدلې وى يا يې زړونه بائيللى وى نو هغوئ دې واپس کور ته لاړ شى او مونږ به دلته د جِلعاد د غر سره ايسار شو.“ نو دوويشت زره واپس لاړل او لس زره ايسار شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6229, 'Judges 7:4', 'Judges', 7, 4, '&nbsp;بيا مالِک خُدائ جدعون ته وفرمائيل، ”تا سره دا سړى اوس هم ډېر زيات دى. هغوئ لاندې اوبو ته بوځه او زۀ به هغوئ ستا دپاره هلته بېل بېل کړم. چې زۀ تا ته ووايم چې دا سړى به تا سره خامخا ځى نو هغه به ځى او چې کوم سړى درته وښايم چې نۀ به ځى نو هغه به نۀ ځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6230, 'Judges 7:5', 'Judges', 7, 5, '&nbsp;جدعون سړى اوبو له بوتلل او مالِک خُدائ هغۀ ته وفرمائيل، ”هغه کسان چې د سپى په شان په ژبه اوبۀ څښى، د هغه ټولو نه جدا کړه چې په خپلو ګوډو باندې ټيټ شى او اوبۀ وڅښى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6231, 'Judges 7:6', 'Judges', 7, 6, '&nbsp;هلته درې سوه سړى داسې وُو چې هغوئ په لَپو کښې اوبۀ راواخستلې او وې څښلې، او نور ټول په خپلو ګوډو باندې ټيټ شول او اوبۀ يې وڅښلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6232, 'Judges 7:7', 'Judges', 7, 7, '&nbsp;مالِک خُدائ جدعون ته وفرمائيل، ”د دې درې سوو سړو په ذريعه چې په لَپو باندې اوبۀ څښى، زۀ به تاسو بچ کړم او په ميديانيانو باندې به فتح درکړم. باقى نور ټول کورونو ته ولېږه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6233, 'Judges 7:8', 'Judges', 7, 8, '&nbsp;نو جدعون هغه ټول بنى اِسرائيليان کور ته ولېږل بغېر د هغه درېو سوو نه، چا چې بيګلې او سامان ساتلے وو. د ميديانيانو کېمپ د هغوئ نه لاندې په مېدان کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6234, 'Judges 7:9', 'Judges', 7, 9, '&nbsp;په هغه شپه مالِک خُدائ جدعون له حُکم ورکړو، ”پاڅه او په خېمو حمله وکړه، زۀ تا له په هغوئ باندې فتح درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6235, 'Judges 7:10', 'Judges', 7, 10, '&nbsp;خو کۀ تۀ د حملې کولو نه يرېږې، نو د خپل نوکر فوراه سره لاندې خېمو ته لاړ شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6236, 'Judges 7:11', 'Judges', 7, 11, '&nbsp;چې هغوئ څۀ وائى نو تۀ به هغه واورې او تا ته به د حملې کولو حوصله مِلاو شى.“ نو جدعون او د هغۀ نوکر فوراه د دشمنانو د خېمو غاړې ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6237, 'Judges 7:12', 'Judges', 7, 12, '&nbsp;ميديانيان، عماليقيان او د صحرا قبيلو سړى د مُولخانو د لښکر په شان په مېدان کښې خوارۀ شوى وُو او د هغوئ اوښان د سمندر د شګو په شان بې‌شمېره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6238, 'Judges 7:13', 'Judges', 7, 13, '&nbsp;کله چې جدعون راورسېدو، هغۀ واورېدل چې يو سړے خپل ملګرى ته خوب بيانوى. هغۀ وفرمائيل، ”ما خوب وليدو چې د اوربشو يو ګول روټۍ راورغړېده او يوه خېمه يې ووهله، خېمه په بل مخ واوړېدله او راوغورزېدله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6239, 'Judges 7:14', 'Judges', 7, 14, '&nbsp;د هغۀ دوست جواب ورکړو، ”دا د بنى اِسرائيلو تُوره ده چې د يوآس زوئ جدعون دے، د دې بل هيڅ مطلب نشته. خُدائ پاک هغۀ له په ميديانيانو او زمونږ په ټول لښکر باندې فتح ورکړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6240, 'Judges 7:15', 'Judges', 7, 15, '&nbsp;کله چې جدعون د هغه سړى د خوب او د هغې د مطلب په حقله واورېدل، نو هغۀ د مالِک خُدائ عبادت وکړو. بيا هغه واپس د بنى اِسرائيلو خېمو ته لاړو او وې فرمائيل، ”پاڅئ، مالِک خُدائ تاسو له د ميديانيانو په لښکر باندې فتح درکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6241, 'Judges 7:16', 'Judges', 7, 16, '&nbsp;هغۀ درې سوه سړى په درېو ډلو کښې تقسيم کړل او هر يو سړى له يې يو بيګل او يو منګے ورکړو چې په کښې به چراغ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6242, 'Judges 7:17', 'Judges', 7, 17, '&nbsp;هغۀ هغوئ ته وفرمائيل، ”زۀ چې کله د خېمو غاړې ته ورسېږم، ما ته ګورئ او چې زۀ څۀ کوم نو هغه شان وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6243, 'Judges 7:18', 'Judges', 7, 18, '&nbsp;کله چې زۀ او زما قبيله بيګلې وغږوُو، بيا تاسو خپلې بيګلې د خېمو نه ګېرچاپېره وغږوئ او داسې نعرې ووهئ، دپاره د مالِک خُدائ او د جدعون.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6244, 'Judges 7:19', 'Judges', 7, 19, '&nbsp;جدعون او د هغۀ سل سړى د نيمې شپې نه لږ مخکښې د خېمو غاړې ته راغلل، هم په هغه وخت پهره دار بدل شوى وُو. بيا هغوئ بيګلې وغږولې او چې د هغوئ سره کوم منګى وُو نو هغه يې مات کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6245, 'Judges 7:20', 'Judges', 7, 20, '&nbsp;او هغه نورو دوو ډلو هم دغه شان وکړل. هغوئ ټولو په خپلو ګسو لاسونو کښې چراغونه نيولى وُو، په ښو لاسونو کښې يې بيګلې وې او چغې يې وهلې، ”تُوره د مالِک خُدائ او جدعون دپاره.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6246, 'Judges 7:21', 'Judges', 7, 21, '&nbsp;ټول سړى د خېمو نه ګېرچاپېره په خپل خپل ځائ باندې ودرېدل او د دشمن ټول لښکر وتښتېدو او چغې يې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6247, 'Judges 7:22', 'Judges', 7, 22, '&nbsp;کله چې د جدعون سړو بيګلې غږولې، نو مالِک خُدائ د دشمن لښکر دې ته جوړ کړو چې د خپلو تُورو سره په يو بل باندې حمله وکړى. هغوئ د بيت‌سِطه پورې د صريرات طرف ته او طبات ته نزدې ابيل‌محوله پورې منډې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6248, 'Judges 7:23', 'Judges', 7, 23, '&nbsp;بيا د نفتالى او آشر قبيلو او د منسى د دواړو برخو نه سړى راوغوښتلے شول او هغوئ په ميديانيانو پسې لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6249, 'Judges 7:24', 'Judges', 7, 24, '&nbsp;جدعون د غرونو مُلک ټول اِفرائيم ته پېغام وړُونکى ولېږل چې ووائى، ”لاندې راشئ او د ميديانيانو سره جنګ وکړئ. د اُردن سيند او د بيت‌باره پورې ټول نِهرونه ونيسئ، چې ميديانيان ترې نه راپورې نۀ وځى.“ نو د اِفرائيم سړى راغونډ کړے شول او هغوئ د اُردن سيند او د بيت‌باره پورې نِهرونه ونيول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6250, 'Judges 7:25', 'Judges', 7, 25, '&nbsp;هغوئ د ميديانيانو دوه مشران، عوريب او زئيب ونيول، عوريب يې د عوريب په ګټ باندې ووژلو او زئيب يې د زئيب د انګورو په لنګرۍ کښې ووژلو. هغوئ په ميديانيانو پسې وُو او د عوريب او زئيب سرونه يې جدعون له راوړل، چې هغه اوس د اُردن نمرخاتۀ طرف ته وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6251, 'Judges 8:1', 'Judges', 8, 1, '&nbsp;بيا د اِفرائيم سړو جدعون ته ووئيل، ”کله چې تۀ د ميديانيانو سره جنګ له تلې نو مونږ دې ولې ونۀ غوښتلو؟ تا مونږ سره داسې سلوک ولې وکړو؟“ او هغوئ ورباندې سخت تنقيد وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6252, 'Judges 8:2', 'Judges', 8, 2, '&nbsp;خو هغۀ وفرمائيل، ”ما چې څۀ کولے شول دا د هغې په نسبت هيڅ هم نۀ دى څۀ چې تاسو کړى دى. کۀ د اِفرائيم سړو لږ څۀ هم کړى دى دا د هغې نه ښۀ دى څۀ چې زما ټولې قبيلې کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6253, 'Judges 8:3', 'Judges', 8, 3, '&nbsp;د دې نه علاوه، د خُدائ پاک د طاقت په ذريعه تاسو د ميديانيانو دوه مشران عوريب او زئيب ووژل. ما داسې څۀ نۀ دى کړى چې ستاسو سره ځان برابر کړم.“ کله چې هغۀ دا وفرمائيل نو د هغوئ غصه سړه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6254, 'Judges 8:4', 'Judges', 8, 4, '&nbsp;په دې وخت کښې جدعون او د هغۀ درې سوه سړى د اُردن سيند له راغلى وُو او د دې نه پورې وتى هم وُو. هغوئ ډېر ستړى وُو، خو بيا هم په دشمن پسې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6255, 'Judges 8:5', 'Judges', 8, 5, '&nbsp;کله چې هغوئ سُکات ته ورسېدل، نو هغۀ د ښار خلقو ته وفرمائيل، ”زما سړو له لږه روټۍ ورکړئ. هغوئ ډېر ستړى دى او زۀ د ميديانيانو بادشاهان زِبح او ضلمنع پسې يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6256, 'Judges 8:6', 'Judges', 8, 6, '&nbsp;خو د سُکات مشرانو ووئيل، ”مونږ ستاسو لښکر له خوراک ولې ورکړو؟ تاسو تر اوسه پورې زِبح او ضلمنع نۀ دى نيولى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6257, 'Judges 8:7', 'Judges', 8, 7, '&nbsp;نو جدعون وفرمائيل، ”ټيک ده. کله چې مالِک خُدائ زِبح او ضلمنع ما ته په حواله کړى، نو ستاسو غوښې به د صحرا په ازغو او غنو باندې وشلوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6258, 'Judges 8:8', 'Judges', 8, 8, '&nbsp;جدعون فنواېل ته لاړو او هلته يې خلقو ته هم دغه شان درخواست وکړو، خو د فنواېل خلقو هم د سُکات د خلقو په شان هم دغه شان جواب ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6259, 'Judges 8:9', 'Judges', 8, 9, '&nbsp;نو هغۀ هغوئ ته وفرمائيل، ”زۀ ځم، په خېر سره به واپس راځم او ستاسو دا برج به راغورزوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6260, 'Judges 8:10', 'Judges', 8, 10, '&nbsp;زِبح او ضلمنع په قرقور کښې د خپل لښکر سره وُو. د صحرا د قبيلو د لښکر نه صِرف پينځلس زره سړى پاتې وُو، يو لاک او شل زره فوجيان وژلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6261, 'Judges 8:11', 'Judges', 8, 11, '&nbsp;جدعون د نوبح او يګبها نمرخاتۀ طرف ته د قافِلو په لاره لاړو او ناڅاپى يې په لښکر باندې حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6262, 'Judges 8:12', 'Judges', 8, 12, '&nbsp;د ميديانيانو دوه بادشاهان زِبح او ضلمنع وتښتېدل، خو هغه ورپسې وُو او وې نيول او د هغوئ ټول لښکر يې په وارخطايۍ آخته کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6263, 'Judges 8:13', 'Judges', 8, 13, '&nbsp;کله چې جدعون د حِرس درې په لاره د جنګ نه واپس روان وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6264, 'Judges 8:14', 'Judges', 8, 14, '&nbsp;هغۀ د سُکات يو زلمے ونيولو او تپوس يې ترې نه وکړو. هغه زلمى جدعون ته د سُکات د اووۀ اوياؤ مشرانو نومونه وليکل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6265, 'Judges 8:15', 'Judges', 8, 15, '&nbsp;بيا جدعون د سُکات خلقو له لاړو او ورته يې وفرمائيل، ”تاسو ته ياد دى چې زما د مدد کولو نه مو اِنکار وکړو؟ او وئيل مو چې مونږ ستا ستړى لښکر له هيڅ خوراک نۀ شو ورکولے ځکه چې تا زِبح او ضلمنع نۀ دى نيولى. نو وګورئ، هغوئ دا دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6266, 'Judges 8:16', 'Judges', 8, 16, '&nbsp;بيا هغۀ د صحرا نه ازغى او غنې يوړې او د سُکات مشرانو له يې ورباندې سزا ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6267, 'Judges 8:17', 'Judges', 8, 17, '&nbsp;هغۀ په فنواېل کښې برج هم راغورزولو او د ښار خلق يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6268, 'Judges 8:18', 'Judges', 8, 18, '&nbsp;بيا جدعون زِبح او ضلمنع نه تپوس وکړو، ”تاسو په تبور کښې څوک وژلى دى؟“ هغوئ جواب ورکړو، ”هغوئ ستا په شان وُو، هر يو کس د بادشاه د زوئ په شان وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6269, 'Judges 8:19', 'Judges', 8, 19, '&nbsp;جدعون ورته وفرمائيل، ”هغوئ زما وروڼه وُو، زما د خپلې مور زامن وُو. زۀ دا قسم خورم کۀ تاسو هغوئ وژلى نۀ وے، نو ما به تاسو نۀ وژلئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6270, 'Judges 8:20', 'Judges', 8, 20, '&nbsp;بيا هغۀ خپل مشر زوئ يتر ته وفرمائيل، ”لاړ شه او هغوئ ووژنه.“ خو هلک خپله تُوره راونۀ ويستله، ځکه چې هغه هلک وو او يرېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6271, 'Judges 8:21', 'Judges', 8, 21, '&nbsp;بيا زِبح او ضلمنع جدعون ته ووئيل، ”راشه او په خپله مونږ ووژنه. څنګه چې سړے وى هغسې يې طاقت وى.“ نو جدعون هغوئ ووژل او هغه ټول کالى يې ترې نه يوړل چې د هغوئ د اوښانو په غاړو کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6272, 'Judges 8:22', 'Judges', 8, 22, '&nbsp;د هغې نه پس، بنى اِسرائيلو جدعون ته ووئيل، ”تۀ او ستا نه پس دې ستا اولاد زمونږ بادشاهان شى ځکه چې تا مونږ د ميديانيانو نه بچ کړى يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6273, 'Judges 8:23', 'Judges', 8, 23, '&nbsp;جدعون جواب ورکړو، ”نۀ به زۀ او نۀ به زما زوئ ستاسو حکمران وى. مالِک خُدائ به په خپله ستاسو حکمران وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6274, 'Judges 8:24', 'Judges', 8, 24, '&nbsp;خو هغۀ خپله خبره جارى وساتله، ”زۀ به ستاسو نه يو څيز وغواړم. هر يو کس دې ما له هغه والۍ راکړى کومې چې تاسو اخستې دى.“ (د ميديانيانو دا رِواج وو چې هغوئ به د سرو زرو والۍ اچولې.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6275, 'Judges 8:25', 'Judges', 8, 25, '&nbsp;خلقو جواب ورکړو، ”مونږ به په داسې کولو خوشحاله شُو.“ هغوئ يوه کپړه خوره کړه او چې هغوئ په لوټ مار کښې کومې د سرو زرو والۍ اخستې وې هغه يې ورباندې کېښودې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6276, 'Judges 8:26', 'Judges', 8, 26, '&nbsp;جدعون ته چې کومې د سرو زرو والۍ مِلاو شوې وې هغه تقريباً شل کلو وې او په دې کښې کالى، هارونه او د کاسنى رنګ جامې شاملې نۀ وې چې د ميديان بادشاهانو اغوستې او هغه پټه هم په کښې شامله نۀ وه چې د هغوئ د اوښانو په غاړه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6277, 'Judges 8:27', 'Judges', 8, 27, '&nbsp;جدعون د سرو زرو يو بُت جوړ کړو او په خپل ښار عفره کښې يې کېښودو. ټولو بنى اِسرائيلو خُدائ پاک پرېښودو او هلته د بُت عبادت له لاړل. دا د جدعون او د هغۀ د خاندان دپاره يو دام جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6278, 'Judges 8:28', 'Judges', 8, 28, '&nbsp;نو ميديانيانو د بنى اِسرائيلو نه شکست وخوړو او هغوئ نور د خطرې سبب نۀ شول. څلوېښت کاله په هغه مُلک کښې امن وو، تر دې پورې چې جدعون مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6279, 'Judges 8:29', 'Judges', 8, 29, '&nbsp;جدعون واپس خپل کور ته لاړو او هلته اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6280, 'Judges 8:30', 'Judges', 8, 30, '&nbsp;د هغۀ اويا زامن وُو، ځکه چې د هغۀ ډېرې ښځې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6281, 'Judges 8:31', 'Judges', 8, 31, '&nbsp;په شِکم کښې د هغۀ يوه وينځه هم وه، د هغې نه يې يو زوئ وشو او ابى‌مَلِک نوم يې پرې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6282, 'Judges 8:32', 'Judges', 8, 32, '&nbsp;د يوآس زوئ جدعون ښۀ په پوخ عُمر کښې مړ شو او د ابيعزر د قبيلې په ښار عفره کښې د خپل پلار په اديره کښې ښخ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6283, 'Judges 8:33', 'Judges', 8, 33, '&nbsp;چې څنګه جدعون مړ شو نو بنى اِسرائيلو بيا د خُدائ پاک سره بې‌غېرتى وکړه او د بعل د بُتانو عبادت يې وکړو. هغوئ يو بُت جوړ کړو چې نوم يې بعل‌بريت وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6284, 'Judges 8:34', 'Judges', 8, 34, '&nbsp;او د مالِک خُدائ خپل خُدائ پاک خِدمت يې نور ونۀ کړو، چا چې هغوئ د ګېرچاپېره د خپلو ټولو دشمنانو نه بچ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6285, 'Judges 8:35', 'Judges', 8, 35, '&nbsp;جدعون چې د بنى اِسرائيلو سره څومره ښۀ کړى وُو نو هغوئ د هغۀ خاندان ته هيڅ وفادارى ونۀ ښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6286, 'Judges 9:1', 'Judges', 9, 1, '&nbsp;د جدعون زوئ ابى‌مَلِک د شِکم ښار ته لاړو، چرته چې د هغۀ د مور ټول خپلوان اوسېدل او هغوئ ته يې ووئيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6287, 'Judges 9:2', 'Judges', 9, 2, '&nbsp;چې د شِکم د خلقو نه تپوس وکړى، ”ستاسو څنګه خوښه ده چې د جدعون اويا واړه زامن درباندې بادشاهى وکړى او يا کۀ صِرف يو کس؟ ياد ساتئ چې ابى‌مَلِک ستاسو خپله وينه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6288, 'Judges 9:3', 'Judges', 9, 3, '&nbsp;د هغۀ د مور خپلوانو د شِکم خلقو سره د دې په حقله د هغۀ دپاره خبره وکړه او د شِکم خلقو دا فېصله وکړه چې د ابى‌مَلِک خبره ومنى ځکه چې هغه يې رشته‌دار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6289, 'Judges 9:4', 'Judges', 9, 4, '&nbsp;هغوئ هغۀ له د بعل‌بريت د لوظ عبادتخانې نه اويا د سپينو زرو سيکې ورکړې او په دې پېسو هغۀ د بې‌کاره بدمعاشانو يوه ډله ځان سره کړه چې ملګرتيا يې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6290, 'Judges 9:5', 'Judges', 9, 5, '&nbsp;هغه په عفره کښې د خپل پلار کور ته لاړو او هلته يې د يو کاڼى دپاسه خپل اويا وروڼه ووژل، چې د جدعون زامن وُو. خو د جدعون کشرے زوئ يوتام پټ شو او ونۀ وژلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6291, 'Judges 9:6', 'Judges', 9, 6, '&nbsp;بيا د شِکم او بيت‌مِلو ټول خلق راغونډ شول او په شِکم کښې د څېړۍ پاکې ونې ته لاړل، چرته چې هغوئ ابى‌مَلِک بادشاه جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6292, 'Judges 9:7', 'Judges', 9, 7, '&nbsp;کله چې يوتام د دې نه خبر شو، نو هغه لاړو او د ګِرزيم د غرۀ په سر ودرېدو او هغوئ ته يې چغې ووهلې، ”اے د شِکم خلقو، تاسو زما خبره واورئ تاسو زما خبره واورئ تر دې چې خُدائ پاک ستاسو خبره واورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6293, 'Judges 9:8', 'Judges', 9, 8, '&nbsp;يو ځل ونې راغونډې شوې چې د ځان دپاره يو بادشاه خوښ کړى. هغوئ د زيتُونو ونې ته ووئيل چې تۀ زمونږ بادشاه شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6294, 'Judges 9:9', 'Judges', 9, 9, '&nbsp;د زيتُونو ونې جواب ورکړو، ولې زۀ دې د زيتُونو تېل ورکول بند کړم کوم چې د معبودانو او انسانانو د درناوى دپاره استعماليږى صرف د دې دپاره چې د نورو ونو مشره شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6295, 'Judges 9:10', 'Judges', 9, 10, '&nbsp;بيا ونو د اينځر ونې ته ووئيل چې، تۀ راشه او زمونږ بادشاه شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6296, 'Judges 9:11', 'Judges', 9, 11, '&nbsp;خو د اينځر ونې جواب ورکړو، ولې زۀ دې خپله خوَږه مېوه پېدا کول بند کړم، صرف د دې دپاره چې د نورو ونو مشره شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6297, 'Judges 9:12', 'Judges', 9, 12, '&nbsp;نو بيا ونو د انګورو بوټى ته ووئيل چې، تۀ راشه او زمونږ بادشاه شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6298, 'Judges 9:13', 'Judges', 9, 13, '&nbsp;خو د انګورو بوټى ورته په جواب کښې ووئيل، ولې زۀ دې خپل مے پېدا کول بند کړم، چې په دې باندې معبودان او انسانان خوشحاليږى، صرف د دې دپاره چې د نورو ونو مشره شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6299, 'Judges 9:14', 'Judges', 9, 14, '&nbsp;نو بيا ټولو ونو د ازغو غنې ته ووئيل چې، تۀ راشه او زمونږ بادشاه شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6300, 'Judges 9:15', 'Judges', 9, 15, '&nbsp;د ازغو غنې جواب ورکړو چې، کۀ تاسو په رښتيا سره ما خپل بادشاه جوړول غواړئ، نو زما د سورى لاندې پناه واخلئ. کۀ تاسو داسې ونۀ کړل نو زما د ازغو څانګو نه به اور بل شى او د لبنان د دِيار ونې به وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');